/* -----------------------------------------------------------------------
 * debug_menu.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 28 Oct 2026 for Tony's display/UI subsystem.
 * BJT2 Sound Modulating Toy — Hidden Debug Screen Navigation
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * Every page and item is described by a const table indexed by its
 * number, so the tables live in flash on the STM32 and the glue can draw
 * a whole list with a simple loop. The only RAM this module touches is
 * the caller's page/item bytes and its debug_hold_t.
 *
 * No task of its own: inside TonyTask, ui_state_machine.c moves the
 * cursor with it, tony_debug.c takes the names and the item actions, and
 * tony_ui.c feeds the BACK-hold detector on every input scan.
 *
 * No HAL functions are called. This file compiles on any host.
 * ----------------------------------------------------------------------- */

#include "debug_menu.h"
#include <stddef.h>

/* Cursor positions per page, in debug_page_t order. */
static const uint8_t s_page_items[DEBUG_PAGE_COUNT] = {
    1U,                     /* DEBUG_PAGE_SYSTEM  — information page       */
    1U,                     /* DEBUG_PAGE_STORAGE — information page       */
    1U,                     /* DEBUG_PAGE_POWER   — information page       */
    DEBUG_SPEAKER_ITEMS,    /* DEBUG_PAGE_SPEAKER — patterns, then tunes   */
    DEBUG_FAULT_ITEMS,      /* DEBUG_PAGE_FAULTS  — fault injections       */
};

static const char *const s_page_titles[DEBUG_PAGE_COUNT] = {
    "System",
    "Storage",
    "Battery / power",
    "Speaker test",
    "Fault injection",
};

/* The 10 test patterns first (Tom_Test_t order from TOM_TEST_SWEEP_100),
 * then the 3 tunes (TomTune_t order). */
static const char *const s_speaker_names[DEBUG_SPEAKER_ITEMS] = {
    "Sweep 100 Hz",
    "Sweep 200 Hz",
    "Sweep 500 Hz",
    "Sweep 1 kHz",
    "Sweep 2 kHz",
    "Sweep 5 kHz",
    "Sweep 8 kHz",
    "Sweep 10 kHz",
    "Left only 1 kHz",
    "Right only 1 kHz",
    "Tune: startup",
    "Tune: critical",
    "Tune: fault beep",
};

/* One Faults item: what it is called, what pushing it does and the SOC
 * override it asks for. The names spell the percentages out, so
 * test_debug_menu.c checks every name still matches its DEBUG_SOC_* value. */
typedef struct {
    const char          *name;
    debug_fault_action_t action;
    uint8_t              soc_pct;
    uint16_t             seconds;
} fault_item_t;

static const fault_item_t s_fault_items[DEBUG_FAULT_ITEMS] = {
    { "Storage fault",   DEBUG_FAULT_ACT_STORAGE,        0U,                 0U                      },
    { "Battery LOW 25%", DEBUG_FAULT_ACT_SOC_OVERRIDE,   DEBUG_SOC_LOW_PCT,  DEBUG_SOC_OVERRIDE_S    },
    { "Battery CRIT 8%", DEBUG_FAULT_ACT_SOC_OVERRIDE,   DEBUG_SOC_CRIT_PCT, DEBUG_SOC_OVERRIDE_S    },
    { "Battery OK 60%",  DEBUG_FAULT_ACT_SOC_OVERRIDE,   DEBUG_SOC_OK_PCT,   DEBUG_SOC_OK_OVERRIDE_S },
    { "Clear overrides", DEBUG_FAULT_ACT_CLEAR_OVERRIDE, 0U,                 0U                      },
};

/* -----------------------------------------------------------------------
 * debug_page_items
 * ----------------------------------------------------------------------- */
uint8_t debug_page_items(uint8_t page)
{
    if (page >= (uint8_t)DEBUG_PAGE_COUNT) {
        return 0U;
    }
    return s_page_items[page];
}

/* -----------------------------------------------------------------------
 * clamp_position  (private)
 * Brings a stale or corrupted page/item back to a valid cursor position
 * before it is moved, so the cursor can never index past a table: a page
 * past the end becomes the last page, an item past the end of its page
 * becomes that page's last item. A valid position is left untouched.
 * ----------------------------------------------------------------------- */
static void clamp_position(uint8_t *page, uint8_t *item)
{
    if (*page >= (uint8_t)DEBUG_PAGE_COUNT) {
        *page = (uint8_t)(DEBUG_PAGE_COUNT - 1);
    }
    if (*item >= s_page_items[*page]) {
        *item = (uint8_t)(s_page_items[*page] - 1U);
    }
}

/* -----------------------------------------------------------------------
 * debug_cursor_next
 * Steps through a list item by item; past its end (or straight away on an
 * information page, which is a single position) moves to the next page.
 * ----------------------------------------------------------------------- */
void debug_cursor_next(uint8_t *page, uint8_t *item)
{
    if (page == NULL || item == NULL) {
        return;
    }
    clamp_position(page, item);

    if ((uint8_t)(*item + 1U) < s_page_items[*page]) {
        *item = (uint8_t)(*item + 1U);
        return;
    }

    /* Past the last item: item 0 of the next page, Faults wraps to System */
    if (*page < (uint8_t)(DEBUG_PAGE_COUNT - 1)) {
        *page = (uint8_t)(*page + 1U);
    } else {
        *page = (uint8_t)DEBUG_PAGE_SYSTEM;
    }
    *item = 0U;
}

/* -----------------------------------------------------------------------
 * debug_cursor_prev
 * Exact reverse of debug_cursor_next. Landing on the LAST item of the
 * previous page (not item 0) is what makes the two inverses of each
 * other: one detent back always undoes one detent forward.
 * ----------------------------------------------------------------------- */
void debug_cursor_prev(uint8_t *page, uint8_t *item)
{
    if (page == NULL || item == NULL) {
        return;
    }
    clamp_position(page, item);

    if (*item > 0U) {
        *item = (uint8_t)(*item - 1U);
        return;
    }

    /* Before item 0: last item of the previous page, System wraps to Faults */
    if (*page > (uint8_t)DEBUG_PAGE_SYSTEM) {
        *page = (uint8_t)(*page - 1U);
    } else {
        *page = (uint8_t)(DEBUG_PAGE_COUNT - 1);
    }
    *item = (uint8_t)(s_page_items[*page] - 1U);
}

/* -----------------------------------------------------------------------
 * Speaker page helpers
 * Items 0..9 are test patterns and 10..12 tunes, so both indices are a
 * plain offset into the item number.
 * ----------------------------------------------------------------------- */
uint8_t debug_speaker_is_tune(uint8_t item)
{
    if (item >= DEBUG_SPEAKER_PATTERNS && item < DEBUG_SPEAKER_ITEMS) {
        return 1U;
    }
    return 0U;
}

uint8_t debug_speaker_pattern_index(uint8_t item)
{
    if (item < DEBUG_SPEAKER_PATTERNS) {
        return item;
    }
    return DEBUG_INDEX_NONE;
}

uint8_t debug_speaker_tune_index(uint8_t item)
{
    if (debug_speaker_is_tune(item) != 0U) {
        return (uint8_t)(item - DEBUG_SPEAKER_PATTERNS);
    }
    return DEBUG_INDEX_NONE;
}

/* -----------------------------------------------------------------------
 * debug_fault_item_action
 * Out of range gives DEBUG_FAULT_ACT_NONE with zeroed outputs, so a
 * caller that ignores the action still never sends a stray override.
 * ----------------------------------------------------------------------- */
debug_fault_action_t debug_fault_item_action(uint8_t item, uint8_t *soc_pct,
                                             uint16_t *seconds)
{
    debug_fault_action_t action = DEBUG_FAULT_ACT_NONE;
    uint8_t              soc    = 0U;
    uint16_t             secs   = 0U;

    if (item < DEBUG_FAULT_ITEMS) {
        action = s_fault_items[item].action;
        soc    = s_fault_items[item].soc_pct;
        secs   = s_fault_items[item].seconds;
    }
    if (soc_pct != NULL) {
        *soc_pct = soc;
    }
    if (seconds != NULL) {
        *seconds = secs;
    }
    return action;
}

/* -----------------------------------------------------------------------
 * Names
 * "?" for anything out of range, never NULL, so the glue can pass the
 * result straight to snprintf without a check.
 * ----------------------------------------------------------------------- */
const char *debug_page_title(uint8_t page)
{
    if (page >= (uint8_t)DEBUG_PAGE_COUNT) {
        return "?";
    }
    return s_page_titles[page];
}

const char *debug_speaker_item_name(uint8_t item)
{
    if (item >= DEBUG_SPEAKER_ITEMS) {
        return "?";
    }
    return s_speaker_names[item];
}

const char *debug_fault_item_name(uint8_t item)
{
    if (item >= DEBUG_FAULT_ITEMS) {
        return "?";
    }
    return s_fault_items[item].name;
}

/* -----------------------------------------------------------------------
 * debug_hold_init
 * ----------------------------------------------------------------------- */
void debug_hold_init(debug_hold_t *h)
{
    if (h == NULL) {
        return;
    }
    h->down     = 0U;
    h->fired    = 0U;
    h->since_ms = 0U;
}

/* -----------------------------------------------------------------------
 * debug_hold_update
 * Rule: fire once per press when held >= DEBUG_HOLD_MS with every update
 * of that press on Home; one update off Home uses the press up until it
 * is released (see the header for why).
 * ----------------------------------------------------------------------- */
uint8_t debug_hold_update(debug_hold_t *h, uint8_t pressed, uint8_t on_home,
                          uint32_t now_ms)
{
    if (h == NULL) {
        return 0U;
    }

    if (pressed == 0U) {
        /* Released: forget this press, the next one needs its own 2 s */
        h->down  = 0U;
        h->fired = 0U;
        return 0U;
    }

    if (h->down == 0U) {
        /* Press edge: start counting from here */
        h->down     = 1U;
        h->fired    = 0U;
        h->since_ms = now_ms;
    }

    if (on_home == 0U) {
        /* Off Home: this press is used up until it is released, even if
         * Home comes back while BACK is still held. */
        h->fired = 1U;
        return 0U;
    }

    /* Unsigned subtraction gives the right elapsed time even if the tick
     * wrapped past 0xFFFFFFFF during the hold. */
    if (h->fired == 0U && (uint32_t)(now_ms - h->since_ms) >= DEBUG_HOLD_MS) {
        h->fired = 1U;      /* once per press: holding on never re-fires */
        return 1U;
    }
    return 0U;
}
